-- REFERENCE ONLY.
create table if not exists review_evidence_manifests (id uuid primary key default gen_random_uuid(), review_cycle_id uuid references periodic_review_cycles(id), sha256 text not null, source_count integer not null, methodology_version text not null, quality_status text not null, created_at timestamptz not null default now());
create table if not exists implementation_reports (id uuid primary key default gen_random_uuid(), participant_id uuid not null, reporting_period tstzrange not null, state text not null, evidence_manifest_id uuid, submitted_at timestamptz, created_at timestamptz not null default now());
create table if not exists protocol_lifecycle_events (id uuid primary key default gen_random_uuid(), protocol_id uuid not null, from_state text, to_state text not null, legal_basis jsonb not null, effective_at timestamptz, audit_event_id uuid not null, created_at timestamptz not null default now());
create table if not exists compliance_review_cases (id uuid primary key default gen_random_uuid(), participant_id uuid not null, state text not null, finding jsonb, corrective_plan jsonb, appeal_deadline timestamptz, created_at timestamptz not null default now());
